<?php
declare(strict_types=1);

/*
 * install_pick_reminder_dashboard_v003_20260906_033416am.php
 * VERSION: v001
 * LAST MODIFIED: 9/6/2026 3:34:16 am
 *
 * PURPOSE:
 * - Upgrade the active Pick Reminder system:
 *     helper v002 -> v003
 *     dashboard v002 -> v003
 *     scheduler v001 -> v002
 * - Extend USER::send_mail() backward-compatibly with optional BCC support.
 * - Keep existing Race Results mail calls unchanged.
 *
 * NEW:
 * - Uses existing Gmail/PHPMailer mail path instead of PHP mail().
 * - Visible To: manliusracingleague@gmail.com.
 * - Team email address(es) are BCC recipients.
 * - One separate message per missing team.
 * - Team name appears in the reminder message.
 * - One-time AUTO TEST timestamp for TEST scope / ID 999.
 * - AUTO TEST exercises the real one-minute cron/scheduler path.
 *
 * SAFETY:
 * - TEST/LIVE protections remain.
 * - LIVE manual still requires SEND LIVE.
 * - LIVE AUTO still requires ENABLE LIVE AUTO.
 * - Installer sends no email.
 * - Full rollback copies are created before Apply.
 */

date_default_timezone_set('America/New_York');

$root=rtrim((string)($_SERVER['DOCUMENT_ROOT']??__DIR__),'/\\');
$helper=$root.'/pick_reminder_helper.php';
$scheduler=$root.'/pick_reminder_scheduler.php';
$dashboard=$root.'/pick_reminder_dashboard.php';
$classUser=$root.'/class.user.php';
$mailerFile=$root.'/mailer/class.phpmailer.php';
$configFile=$root.'/_pick_reminder/config.json';

$backupDir=$root.'/_migration_backups/pick_reminder_dashboard_v003_20260906_033416am';
$backupHelper=$backupDir.'/pick_reminder_helper.php';
$backupScheduler=$backupDir.'/pick_reminder_scheduler.php';
$backupDashboard=$backupDir.'/pick_reminder_dashboard.php';
$backupClassUser=$backupDir.'/class.user.php';
$backupConfig=$backupDir.'/config.json';

$payloadHelper='';
$payloadScheduler='';
$payloadDashboard='';

function prv3_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function prv3_dec(string $s):string{$d=base64_decode($s,true);return is_string($d)?$d:'';}
function prv3_atomic(string $path,string $content):array{
    try{$suffix=bin2hex(random_bytes(4));}catch(Throwable $e){$suffix=(string)mt_rand(100000,999999);}
    $tmp=$path.'.tmp_'.$suffix;
    if(@file_put_contents($tmp,$content,LOCK_EX)===false)return [false,'Could not write temporary file: '.$tmp];
    if(!@rename($tmp,$path)){@unlink($tmp);return [false,'Could not replace '.$path];}
    return [true,''];
}
function prv3_lint(string $path):array{
    $cmd=escapeshellarg(PHP_BINARY?:'php').' -l '.escapeshellarg($path).' 2>&1';
    $out=[];$code=1;@exec($cmd,$out,$code);
    if($code===0)return [true,implode("\n",$out)];
    if(!$out)return [null,'PHP CLI syntax check unavailable.'];
    return [false,implode("\n",$out)];
}

$hc=is_file($helper)?(string)@file_get_contents($helper):'';
$sc=is_file($scheduler)?(string)@file_get_contents($scheduler):'';
$dc=is_file($dashboard)?(string)@file_get_contents($dashboard):'';
$uc=is_file($classUser)?(string)@file_get_contents($classUser):'';

$classSigAnchor='public function send_mail($email, $message, $subject)';
$classAddressAnchor='$mail->AddAddress($email);';

$checks=[
    'pick_reminder_helper.php exists'=>is_file($helper),
    'pick_reminder_helper.php writable'=>is_file($helper)&&is_writable($helper),
    'Expected helper v002 baseline'=>strpos($hc,'VERSION: v002')!==false && strpos($hc,'function mrlpr_test_auto_sent')===false,
    'pick_reminder_scheduler.php exists'=>is_file($scheduler),
    'pick_reminder_scheduler.php writable'=>is_file($scheduler)&&is_writable($scheduler),
    'Expected scheduler v001 baseline'=>strpos($sc,'VERSION: v001')!==false && strpos($sc,'AUTO_TEST')===false,
    'pick_reminder_dashboard.php exists'=>is_file($dashboard),
    'pick_reminder_dashboard.php writable'=>is_file($dashboard)&&is_writable($dashboard),
    'Expected dashboard v002 baseline'=>strpos($dc,'VERSION v002 | Admin-only')!==false,
    'class.user.php exists'=>is_file($classUser),
    'class.user.php writable'=>is_file($classUser)&&is_writable($classUser),
    'class.user.php send_mail signature anchor'=>substr_count($uc,$classSigAnchor)===1,
    'class.user.php AddAddress anchor'=>substr_count($uc,$classAddressAnchor)===1,
    'Existing PHPMailer file'=>is_file($mailerFile),
    'public_html writable'=>is_writable($root),
];
$ready=!in_array(false,$checks,true);

$msg='';$type='';

if(($_POST['action']??'')==='apply'){
    if(!$ready){
        $msg='APPLY BLOCKED — required preflight checks are not all passing.';$type='err';
    }else{
        if(!is_dir($backupDir)&&!@mkdir($backupDir,0755,true)){
            $msg='APPLY FAILED — could not create rollback folder.';$type='err';
        }else{
            $backupOk=@copy($helper,$backupHelper)
                && @copy($scheduler,$backupScheduler)
                && @copy($dashboard,$backupDashboard)
                && @copy($classUser,$backupClassUser);

            if(is_file($configFile))$backupOk=$backupOk&&@copy($configFile,$backupConfig);

            if(!$backupOk){
                $msg='APPLY FAILED — could not create all rollback copies.';$type='err';
            }else{
                $err='';

                // Backward-compatible optional BCC support in the existing mailer method.
                $newClass=$uc;
                $newClass=str_replace(
                    $classSigAnchor,
                    'public function send_mail($email, $message, $subject, $bccEmails = array())',
                    $newClass,$c1
                );

                $bccBlock=<<<'PHP'
$mail->AddAddress($email);

        // Optional BCC list for callers that need recipient privacy.
        // Existing 3-argument send_mail() calls are unchanged.
        if (!is_array($bccEmails)) {
            $bccEmails = array($bccEmails);
        }
        foreach ($bccEmails as $bccEmail) {
            $bccEmail = trim((string)$bccEmail);
            if ($bccEmail === '') {
                continue;
            }
            if (strcasecmp($bccEmail, (string)$email) === 0) {
                continue;
            }
            $mail->AddBCC($bccEmail);
        }
PHP;

                $newClass=str_replace($classAddressAnchor,$bccBlock,$newClass,$c2);

                if($c1!==1||$c2!==1){
                    $err='class.user.php anchors did not match exactly during Apply.';
                }

                if($err===''){
                    foreach([
                        [$classUser,$newClass],
                        [$helper,prv3_dec($payloadHelper)],
                        [$scheduler,prv3_dec($payloadScheduler)],
                        [$dashboard,prv3_dec($payloadDashboard)],
                    ] as $pair){
                        [$ok,$why]=prv3_atomic($pair[0],$pair[1]);
                        if(!$ok){$err=$why;break;}
                    }
                }

                if($err===''){
                    foreach([$classUser,$helper,$scheduler,$dashboard] as $path){
                        [$ok,$report]=prv3_lint($path);
                        if($ok===false){$err='PHP syntax check failed for '.basename($path).': '.$report;break;}
                    }
                }

                // If a saved config exists and still has the original stock v001/v002
                // message, migrate only that stock text. Custom user text is preserved.
                if($err==='' && is_file($configFile)){
                    $raw=(string)@file_get_contents($configFile);
                    $cfg=json_decode($raw,true);
                    if(is_array($cfg)){
                        $old="Just a reminder that you have not submitted your picks for {year} {segment_name}.\nThey are due soon — {deadline}.\n{team_page}\nThanks, Steve";
                        $new="Just a reminder that {team_name} has not submitted its picks for {year} {segment_name}.\nThey are due soon — {deadline}.\n{team_page}\nThanks, Steve";
                        if((string)($cfg['body_template']??'')===$old)$cfg['body_template']=$new;
                        if(!array_key_exists('to_email',$cfg))$cfg['to_email']='manliusracingleague@gmail.com';
                        if(!array_key_exists('test_auto_enabled',$cfg))$cfg['test_auto_enabled']=false;
                        if(!array_key_exists('test_auto_at',$cfg))$cfg['test_auto_at']='';
                        $json=json_encode($cfg,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
                        if(is_string($json)){
                            [$ok,$why]=prv3_atomic($configFile,$json.PHP_EOL);
                            if(!$ok)$err='Could not migrate existing Pick Reminder config: '.$why;
                        }
                    }
                }

                if($err!==''){
                    @copy($backupClassUser,$classUser);
                    @copy($backupHelper,$helper);
                    @copy($backupScheduler,$scheduler);
                    @copy($backupDashboard,$dashboard);
                    if(is_file($backupConfig))@copy($backupConfig,$configFile);
                    $msg='APPLY FAILED — '.$err.' Original files restored.';$type='err';
                }else{
                    $msg='INSTALL COMPLETE — Pick Reminder v003 is installed. No email was sent. Current saved mode/scope are preserved; TEST AUTO is off unless you explicitly enable it.';$type='ok';
                }
            }
        }
    }
}

if(($_POST['action']??'')==='rollback'){
    $needed=is_file($backupClassUser)&&is_file($backupHelper)&&is_file($backupScheduler)&&is_file($backupDashboard);
    if(!$needed){
        $msg='ROLLBACK NOT AVAILABLE — rollback copies do not exist yet.';$type='err';
    }else{
        $ok=@copy($backupClassUser,$classUser)
            && @copy($backupHelper,$helper)
            && @copy($backupScheduler,$scheduler)
            && @copy($backupDashboard,$dashboard);
        if(is_file($backupConfig))$ok=$ok&&@copy($backupConfig,$configFile);
        $msg=$ok?'ROLLBACK COMPLETE — Pick Reminder files and class.user.php restored to their pre-v003 state.':'ROLLBACK FAILED.';
        $type=$ok?'ok':'err';
    }
}
?>
